/* gramschmidt.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <stddef.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gramschmidt.h"

/* Tunable blocking factor for the inner loops over the column index j.
   This can be overridden at compile time, e.g.:
     -DGRAMSCHMIDT_TILE_J=256
   It must be strictly positive. */
#ifndef GRAMSCHMIDT_TILE_J
# define GRAMSCHMIDT_TILE_J 128
#endif


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j;

  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      A[i][j] = (((DATA_TYPE) ((i*j) % m) / m )*100) + 10;
      Q[i][j] = 0.0;
    }
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      R[i][j] = 0.0;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("R");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, R[i][j]);
    }
  POLYBENCH_DUMP_END("R");

  POLYBENCH_DUMP_BEGIN("Q");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, Q[i][j]);
    }
  POLYBENCH_DUMP_END("Q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* QR Decomposition with Modified Gram Schmidt:
   http://www.inf.ethz.ch/personal/gander/ */
static
void kernel_gramschmidt[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;

  /* Local restricted views of the matrices.
     PolyBench uses row-major storage: A[i][j] and Q[i][j] are
     contiguous in j for a fixed i.  Using local restrict-qualified
     pointers helps the compiler assume non-aliasing between A, R and
     Q and enables better vectorization. */
  DATA_TYPE (*restrict A_)[N] = (DATA_TYPE (*)[N]) A;
  DATA_TYPE (*restrict R_)[N] = (DATA_TYPE (*)[N]) R;
  DATA_TYPE (*restrict Q_)[N] = (DATA_TYPE (*)[N]) Q;

  /* Local copies of the polybench loop bounds.  This avoids repeated
     macro expansion and gives the compiler concrete constants to work
     with when possible. */
  const int mPB = _PB_M;
  const int nPB = _PB_N;

#pragma scop
  for (k = 0; k < nPB; k++)
    {
      /* 1. Compute the 2-norm of k-th column of A. */
      DATA_TYPE nrm = SCALAR_VAL(0.0);
      for (i = 0; i < mPB; i++)
      {
        DATA_TYPE aik = A_[i][k];
        nrm += aik * aik;
      }

      DATA_TYPE rkk = SQRT_FUN(nrm);
      R_[k][k] = rkk;

      /* 2. Normalize k-th column: Q[*,k] = A[*,k] / R[k][k].
         Using an explicit reciprocal avoids a division in the inner
         loop while keeping the mathematical operation Q = A / R. */
      DATA_TYPE inv_rkk = SCALAR_VAL(1.0) / rkk;
      for (i = 0; i < mPB; i++)
        Q_[i][k] = A_[i][k] * inv_rkk;

      /* 3. Initialize the rest of row k of R to zero (j > k).
         R[k][j] is contiguous in j, so memset provides a fast,
         cache-friendly initialization. */
      if (k + 1 < nPB)
      {
        size_t len = (size_t)(nPB - (k + 1));
        memset(&R_[k][k + 1], 0, len * sizeof(DATA_TYPE));
      }

      /* 4. Compute R[k][j] = Q[*,k]^T * A[*,j] for all j > k.
         The original code used:
             for (j = k+1; j < n; j++)
               for (i = 0; i < m; i++)
                 R[k][j] += Q[i][k] * A[i][j];

         We reorder the loops to:
             for (i)
               for (j)

         so that A[i][j] and R[k][j] are both traversed in the
         innermost j-loop, which is contiguous in memory and much more
         cache- and SIMD-friendly.

         For each fixed (k,j), the summation over i is still performed
         in the same order (i from 0 to m-1), so the scalar result
         R[k][j] is mathematically identical to the original code. */
      for (i = 0; i < mPB; i++)
      {
        const DATA_TYPE qik = Q_[i][k];
        DATA_TYPE *restrict Ai = A_[i];
        DATA_TYPE *restrict Rk = R_[k];

        for (int jb = k + 1; jb < nPB; jb += GRAMSCHMIDT_TILE_J)
        {
          int jend = jb + GRAMSCHMIDT_TILE_J;
          if (jend > nPB)
            jend = nPB;

          /* Hint the compiler that there are no loop-carried
             dependencies preventing vectorization. */
#pragma GCC ivdep
          for (j = jb; j < jend; j++)
            Rk[j] += qik * Ai[j];
        }
      }

      /* 5. Update the remaining columns of A:
             A[*,j] -= Q[*,k] * R[k][j]  for all j > k.

         Again we use (i outer, j inner) ordering to get contiguous
         accesses to A[i][j] and R[k][j].  Each A[i][j] is updated
         exactly once, so changing the loop order does not change the
         computation for any element. */
      for (i = 0; i < mPB; i++)
      {
        const DATA_TYPE qik = Q_[i][k];
        DATA_TYPE *restrict Ai = A_[i];
        DATA_TYPE *restrict Rk = R_[k];

        for (int jb = k + 1; jb < nPB; jb += GRAMSCHMIDT_TILE_J)
        {
          int jend = jb + GRAMSCHMIDT_TILE_J;
          if (jend > nPB)
            jend = nPB;

#pragma GCC ivdep
          for (j = jb; j < jend; j++)
            Ai[j] -= qik * Rk[j];
        }
      }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(R,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(Q,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(R),
	      POLYBENCH_ARRAY(Q));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gramschmidt (m, n,
		      POLYBENCH_ARRAY(A),
		      POLYBENCH_ARRAY(R),
		      POLYBENCH_ARRAY(Q));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(R), POLYBENCH_ARRAY(Q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(R);
  POLYBENCH_FREE_ARRAY(Q);

  return 0;
}

