/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gramschmidt.h"

/* Tunable blocking factor for traversals along the column (j) dimension.
 * You can adjust this at compile time, e.g.:
 *   gcc -DGRAMSCHMIDT_JBLOCK=64 ...
 * to better match a particular cache hierarchy.
 */
#ifndef GRAMSCHMIDT_JBLOCK
#define GRAMSCHMIDT_JBLOCK 64
#endif


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j;

  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      A[i][j] = (((DATA_TYPE) ((i*j) % m) / m )*100) + 10;
      Q[i][j] = 0.0;
    }
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      R[i][j] = 0.0;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("R");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, R[i][j]);
    }
  POLYBENCH_DUMP_END("R");

  POLYBENCH_DUMP_BEGIN("Q");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, Q[i][j]);
    }
  POLYBENCH_DUMP_END("Q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* QR Decomposition with Modified Gram Schmidt:
 http://www.inf.ethz.ch/personal/gander/ */
static
void kernel_gramschmidt [[gnu::flatten, gnu::noinline]] (int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE nrm;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      /* 1. Compute the L2 norm of the k-th column of A.
       *    Access is along a column (stride-n), which is inherent to the
       *    algorithm. We keep the reduction order identical to the
       *    original code to preserve numerical behavior.
       */
      nrm = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_M; i++)
      {
        DATA_TYPE A_ik = A[i][k];
        nrm += A_ik * A_ik;
      }

      /* 2. Normalize the k-th column to obtain the k-th column of Q.
       *    We store R[k][k] in a scalar (R_kk) to avoid repeated loads
       *    from memory while keeping exactly the same arithmetic expression
       *    A[i][k] / R[k][k] as in the original code.
       */
      DATA_TYPE R_kk = SQRT_FUN(nrm);
      R[k][k] = R_kk;

      for (i = 0; i < _PB_M; i++)
        Q[i][k] = A[i][k] / R_kk;

      /* Columns to the right of k. */
      int jp = k + 1;
      int np = _PB_N - jp; /* number of remaining columns */

      if (np > 0)
      {
        /* Pointer to the contiguous slice R[k][jp.._PB_N-1]. We will
         * repeatedly update this row; keeping a pointer improves the
         * compiler's ability to optimize address arithmetic.
         */
        DATA_TYPE *restrict Rk = &R[k][jp];

        /* 3. Compute R[k][j] = Q[:,k]^T * A[:,j] for j > k.
         *
         * Original code (for each k):
         *   for (j = k+1; j < N; j++) {
         *     R[k][j] = 0;
         *     for (i = 0; i < M; i++)
         *       R[k][j] += Q[i][k] * A[i][j];
         *   }
         *
         * We reorganize the loops to:
         *
         *   - Initialize the whole R[k][jp..] row once.
         *   - Then, for each row i, update all R[k][jp..] using contiguous
         *     slices of A[i][jp..].
         *
         * For each individual R[k][j], the sequence of operations
         * (initialization followed by accumulation over i = 0..M-1)
         * remains exactly the same as in the original code; therefore the
         * floating-point rounding behavior for each entry R[k][j] is
         * preserved. Only the *order across different j* changes, which
         * is independent.
         */

        /* Initialize R[k][j] = 0 for all j > k. */
        for (j = 0; j < np; j++)
          Rk[j] = SCALAR_VAL(0.0);

        /* Accumulate R[k][jp..] = Q[:,k]^T * A[:,jp..].
         * Loop order: i outer, j inner. For each fixed i we operate on
         * A[i][jp..] and R[k][jp..], which are contiguous in memory.
         * This greatly improves cache locality and enables efficient
         * vectorization along the inner j loop.
         */
        for (i = 0; i < _PB_M; i++)
        {
          DATA_TYPE q_ik = Q[i][k];
          /* Pointer to the part of row i starting at column jp. */
          DATA_TYPE *restrict A_row_ij = &A[i][jp];

          int j_main_end = (np / GRAMSCHMIDT_JBLOCK) * GRAMSCHMIDT_JBLOCK;
          int j0 = 0;

          /* Process full blocks of size GRAMSCHMIDT_JBLOCK. This explicit
           * blocking factor is a tuning parameter that can be adjusted
           * at compile time (GRAMSCHMIDT_JBLOCK) to better match cache
           * and vector widths on a given machine.
           */
          for (; j0 < j_main_end; j0 += GRAMSCHMIDT_JBLOCK)
          {
            DATA_TYPE *restrict A_block = A_row_ij + j0;
            DATA_TYPE *restrict R_block = Rk + j0;

#pragma GCC ivdep
            for (int jj = 0; jj < GRAMSCHMIDT_JBLOCK; jj++)
              R_block[jj] += q_ik * A_block[jj];
          }

          /* Handle any remaining columns in this row. */
#pragma GCC ivdep
          for (; j0 < np; j0++)
            Rk[j0] += q_ik * A_row_ij[j0];
        }

        /* 4. Update the trailing submatrix:
         *      A[:,jp..] = A[:,jp..] - Q[:,k] * R[k][jp..]
         *
         * Original code (for each k, j):
         *   for (j = k+1; j < N; j++) {
         *     ...
         *     for (i = 0; i < M; i++)
         *       A[i][j] = A[i][j] - Q[i][k] * R[k][j];
         *   }
         *
         * Each A[i][j] is updated exactly once based on the fully
         * computed R[k][j], and there is no cross-element dependency.
         * We interchange loops so that we traverse A and R by rows,
         * which yields contiguous memory access and better cache use.
         * Since every (i,j) is still assigned from its previous value
         * with the same expression, the result is bitwise identical.
         */
        for (i = 0; i < _PB_M; i++)
        {
          DATA_TYPE q_ik = Q[i][k];
          DATA_TYPE *restrict A_row_ij = &A[i][jp];

          int j_main_end = (np / GRAMSCHMIDT_JBLOCK) * GRAMSCHMIDT_JBLOCK;
          int j0 = 0;

          /* Blocked, vectorizable update along columns. */
          for (; j0 < j_main_end; j0 += GRAMSCHMIDT_JBLOCK)
          {
            DATA_TYPE *restrict A_block = A_row_ij + j0;
            DATA_TYPE *restrict R_block = Rk + j0;

