            for (int jj = 0; jj < GRAMSCHMIDT_JBLOCK; jj++)
              A_block[jj] -= q_ik * R_block[jj];
          }

          /* Remainder columns. */
#pragma GCC ivdep
          for (; j0 < np; j0++)
            A_row_ij[j0] -= q_ik * Rk[j0];
        }
      }
    }
#pragma endscop

}


