/* QR Decomposition with Modified Gram Schmidt:
   http://www.inf.ethz.ch/personal/gander/ */
static
void kernel_gramschmidt [[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;

  /* Use PolyBench loop bounds; these may be <= m,n (e.g., for reduced sizes). */
  const int pb_m = _PB_M;
  const int pb_n = _PB_N;

  /* Local 'restrict' views of the arrays to aid alias analysis and
   * vectorization.  A, R, and Q are distinct arrays by construction. */
  DATA_TYPE (* restrict a)[n] = A;
  DATA_TYPE (* restrict r)[n] = R;
  DATA_TYPE (* restrict q)[n] = Q;

  const int J_BLOCK = GRAMSCHMIDT_J_BLOCK;

  DATA_TYPE nrm;

#pragma scop
  for (k = 0; k < pb_n; k++)
    {
      /* 1) Compute the Euclidean norm of the k-th column of A. */
      nrm = SCALAR_VAL(0.0);
      for (i = 0; i < pb_m; i++)
        {
          DATA_TYPE val = a[i][k];
          nrm += val * val;
        }

      DATA_TYPE Rkk = SQRT_FUN(nrm);
      r[k][k] = Rkk;

      /* 2) Normalize column k to obtain Q(:,k).
       *
       * Use reciprocal to replace division in the inner loop:
       * Q[i][k] = A[i][k] / Rkk  ==>  Q[i][k] = A[i][k] * (1 / Rkk)
       */
      DATA_TYPE invRkk = SCALAR_VAL(1.0) / Rkk;
      for (i = 0; i < pb_m; i++)
        q[i][k] = a[i][k] * invRkk;

      /* Pointer to row k of R for reuse in the j-block loops. */
      DATA_TYPE * restrict r_k = r[k];

      /* 3) Orthogonalize remaining columns j > k against Q(:,k).
       *
       * We tile the j-loop so that, for a fixed row i, we walk
       * A[i][jb..jend-1] and R[k][jb..jend-1] contiguously in memory.
       * This significantly improves cache locality on row-major data.
       *
       * Algebraically, for the current k we are computing:
       *   R[k, j]   = Q(:,k)^T * A(:,j)
       *   A(:, j)   = A(:, j) - Q(:,k) * R[k, j]
       *
       * These operations are independent across j, so blocking and
       * reordering across different columns does not change results.
       */
      for (int jb = k + 1; jb < pb_n; jb += J_BLOCK)
        {
          int jend = jb + J_BLOCK;
          if (jend > pb_n)
            jend = pb_n;
          const int block_width = jend - jb;

          /* Initialize R[k][j] = 0 for this block. */
          for (j = jb; j < jend; j++)
            r_k[j] = SCALAR_VAL(0.0);

          /* 3a) Compute R[k][j] = Q(:,k)^T * A(:,j) for j in [jb, jend).
           *
           * For each row i, we reuse q[i][k] and traverse contiguous
           * slices of A and R, enabling efficient vectorization.
           */
          for (i = 0; i < pb_m; i++)
            {
              const DATA_TYPE qik = q[i][k];
              DATA_TYPE * restrict a_i_block = &a[i][jb];
              DATA_TYPE * restrict r_k_block = &r_k[jb];

#pragma GCC ivdep
              for (j = 0; j < block_width; j++)
                r_k_block[j] += qik * a_i_block[j];
            }

          /* 3b) Update A(:,j) -= Q(:,k) * R[k][j] for j in [jb, jend).
           *
           * Again, for a fixed row i we touch a contiguous slice of A.
           */
          for (i = 0; i < pb_m; i++)
            {
              const DATA_TYPE qik = q[i][k];
              DATA_TYPE * restrict a_i_block = &a[i][jb];
              DATA_TYPE * restrict r_k_block = &r_k[jb];

#pragma GCC ivdep
              for (j = 0; j < block_width; j++)
                a_i_block[j] -= qik * r_k_block[j];
            }
        }
    }
#pragma endscop

